      "path": "lib/host.js",
      "content": "import { existsSync, readdirSync, readFileSync, realpathSync, statSync, unlinkSync } from 'node:fs'\nimport { isAbsolute, join as joinPath, normalize, resolve as pathResolve } from 'node:path'\nimport { fileURLToPath } from 'node:url'\nimport * as sdkDts from './sdk-dts.mjs'\nimport * as knowledge from './knowledge.mjs'\nimport { startPanel } from './panel.mjs'\nimport { createHdcCore } from './hdc-core.mjs'\nimport { codeHint, SIGN_HINT } from './errors.mjs'\nimport * as studio from './studio.mjs'\nimport * as devcli from './devecocli.mjs'\nimport * as cltModule from './clt.mjs'\nimport * as verDetect from './version-detect.mjs'\nimport * as compileCli from './compile-cli.mjs'\nimport * as compileOut from './compile-output.mjs'\nimport { setSessionCwd as setCompileCwd, getSessionCwd as getCompileCwd, isHarmonyApplicationRoot } from './compile-session-cwd.mjs'\nimport { createBudget } from './async-budget.mjs'\nimport { SKILLS } from './skills.mjs'\n\nexport const name = 'hdc-bridge'\nexport const inject = ['shell', 'tools']\n\n// Cross-layer quoting fidelity (three parsers stand between the user's\n// command text and the device shell: host shell -> hdc arg-join -> on-device\n// sh). Escaping is done per layer with each layer's own rules.\nconst BACKSLASH = String.fromCharCode(92)\nconst APOS = \"'\"\nconst psQuote = (s) => \"'\" + String(s).replace(/'/g, \"''\") + \"'\"\n// PowerShell's '' escape and POSIX quote-splicing are NOT interchangeable:\n// in POSIX shells two adjacent quotes close and reopen with an EMPTY middle\n// ('it''s' parses as its), so passing psQuote output through a bash host or\n// relying on it at the device layer silently drops characters. Each quoting\n// layer gets its own helper; see dcFidelityCommand below.\nconst posixQuote = (s) => \"'\" + String(s).replace(/'/g, \"'\" + BACKSLASH + \"''\") + \"'\"\nconst dcFidelityCommand = (command, flavor) => {\n  // Leave device-shell syntax untouched. A backslash before an apostrophe is\n  // literal inside HarmonyOS sh double quotes and can cause `no closing quote`.\n  return flavor === 'pwsh' ? psQuote(command) : posixQuote(command)\n}\n\n// Test-only seam: pure quoting helpers, so smoke can round-trip them against\n// real shells without booting a profile (see scripts/smoke.mjs section 10).\nexport const _quoting = { psQuote, posixQuote, dcFidelityCommand }\n\n// Node runtime of a DevEco Studio install (<root>/tools/node[/bin]) and of a\n// standalone Command Line Tools distribution (<root>/node[/bin]) — pure path\n// probes shared by the compile tools and the hvigorv fallback.\nexport function studioNodeBin(root) {\n  const win = joinPath(root, 'tools', 'node', 'node.exe')\n  if (existsSync(win)) return win\n  const posix = joinPath(root, 'tools', 'node', 'bin', 'node')\n  return existsSync(posix) ? posix : ''\n}\nexport function cltNodeBin(root) {\n  const win = joinPath(root, 'node', 'node.exe')\n  if (existsSync(win)) return win\n  const posix = joinPath(root, 'node', 'bin', 'node')\n  return existsSync(posix) ? posix : ''\n}\n// arkts_check picks its own runtime: Studio first, then a standalone Command\n// Line Tools install (issue #12).\nexport function arktsRuntimeFrom(studioRoot, cltRoot) {\n  if (studioRoot) {\n    const node = studioNodeBin(studioRoot)\n    if (node) return { root: studioRoot, node }\n  }\n  if (cltRoot) {\n    const node = cltNodeBin(cltRoot)\n    if (node) return { root: cltRoot, node }\n  }\n  return { root: '', node: '' }\n}\n// Command head for the hvigorw launcher. A CLT without bin/ ships\n// hvigor/bin/hvigorw.js as plain JavaScript with no shebang, so a `js` entry\n// must run under a node runtime — the toolchain's own when present (issue #11).\nexport function hvigorCommandHead(hvigor, node, flavor) {\n  const quote = (value) => (flavor === 'pwsh' ? psQuote(value) : posixQuote(value))\n  if (!hvigor || hvigor.kind !== 'js') return quote((hvigor && hvigor.path) || '')\n  return quote(node || 'node') + ' ' + quote(hvigor.path)\n}\n// Test-only seam: pure toolchain helpers, exercised against fixture trees.\nexport const _toolchain = { studioNodeBin, cltNodeBin, arktsRuntimeFrom, hvigorCommandHead }\n\nexport function apply(ctx) {\n  const shell = ctx.shell\n  const sandboxPolicy = ctx.get('sandboxPolicy')\n  const sessionsService = ctx.get('sessions')\n  const fsService = ctx.get('fs')\n  // Official logging convention is ctx.logger; fall back to console when the\n  // logger service is absent (e.g. bare smoke harnesses).\n  const logInfo = (msg) => {\n    if (ctx.logger && typeof ctx.logger.info === 'function') ctx.logger.info(msg)\n    else console.log(msg)\n  }\n\n  function realmSession() {\n    if (!sessionsService || typeof sessionsService.list !== 'function') return undefined\n    try {\n      const list = sessionsService.list()\n      return list.length === 1 ? list[0] : undefined\n    } catch {\n      return undefined\n    }\n  }\n\n  // Resolve the per-call sandbox policy like the official pwsh tool does:\n  // the calling session's immutable cwd is the workspace boundary. Without a\n  // session, fall back to the deployment policy (the executor's own default).\n  function resolvePolicyFor(exec) {\n    if (!sandboxPolicy || typeof sandboxPolicy.resolve !== 'function') return undefined\n    try {\n      if (exec && exec.agent && exec.agent.session) return sandboxPolicy.resolve({ session: exec.agent.session })\n      const session = realmSession()\n      if (session) return sandboxPolicy.resolve({ session })\n      return sandboxPolicy.resolve({})\n    } catch {\n      return undefined\n    }\n  }\n\n  function policyRoot(policy) {\n    return policy && typeof policy.workspaceRoot === 'string' && policy.workspaceRoot ? policy.workspaceRoot : ''\n  }\n\n  // --- environment-level command gating ------------------------------------\n  // The Windows sandbox runner refuses to start when its private temp root sits\n  // inside the policy root, and dsh-base sets the deployment policy root to\n  // process.cwd(): a DSH launched from the user profile therefore cannot run any\n  // session-less sandboxed command. A verdict measured under such a policy\n  // describes the environment, not the toolchain — so it is neither trusted nor\n  // cached (see ensureCli).\n  const ENV_FAILURE_RE = /no sandbox backend|sandbox mode |Unsupported DSH shell seam|refusing to run|EPERM|EACCES|Access is denied/i\n  function isEnvFailure(message) { return ENV_FAILURE_RE.test(String(message || '')) }\n  function normSpecPath(value) { return String(value || '').replace(/\\//g, '\\\\').replace(/\\\\+$/, '').toLowerCase() }\n  function pathContains(root, candidate) {\n    const r = normSpecPath(root)\n    const c = normSpecPath(candidate)\n    return !!r && !!c && (c === r || c.startsWith(r + '\\\\'))\n  }\n  function isSessionPolicy(policy) { return !!(policy && typeof policy.sessionId === 'string' && policy.sessionId) }\n  function policyBlockedReason(policy) {\n    const root = policyRoot(policy)\n    const temp = (typeof process !== 'undefined' && process.env && (process.env.TEMP || process.env.TMP)) || ''\n    if (root && temp && pathContains(root, temp)) {\n      return 'the sandbox policy root ' + root + ' contains the OS temp directory (' + temp + '), which the Windows sandbox runner rejects; start DSH from a directory outside the temp tree'\n    }\n    return 'no usable sandbox policy for this call'\n  }\n  // True only when a command provably cannot run under this policy. An absent\n  // policy is left to the probe (and to the environment-failure path in ensureCli).\n  function policyRunnable(policy) {\n    if (!policy) return true\n    if (typeof process === 'undefined' || process.platform !== 'win32') return true\n    const root = policyRoot(policy)\n    const temp = (process.env && (process.env.TEMP || process.env.TMP)) || ''\n    if (!root || !temp) return true\n    return !pathContains(root, temp)\n  }\n\n  const tailText = (text, max