run before any hdc discovery, and\n  // probing with the wrong default used to cache a bogus failure for the rest\n  // of the process (issue #9).\n  let shellFlavor = (typeof process !== 'undefined' && process.platform === 'win32') ? 'pwsh' : 'bash'\n  let shellFlavorDetected = false\n  let cliCache\n  let cliCacheFlavor = ''\n  function dropCliCache(reason) {\n    if (cliCache) logInfo('[hdc-bridge] devecocli cache dropped (' + reason + ')')\n    cliCache = undefined\n    cliCacheFlavor = ''\n  }\n  async function detectShellFlavor(policy) {\n    if (shellFlavorDetected) return shellFlavor\n    shellFlavorDetected = true // set before probing, so runShellRaw cannot recurse\n    try {\n      const r = await runShellRaw('$PSVersionTable.PSVersion.Major', 8000, 2048, policy)\n      const t = ((r.stdout && r.stdout.text) || '').trim()\n      const probeText = t + '\\n' + ((r.stderr && r.stderr.text) || '')\n      if (/^\\d+(\\.\\d+)*$/.test(t)) {\n        shellFlavor = 'pwsh' // conclusive: PowerShell answered with a version\n      } else if ((t || r.exitCode !== 0) && !isEnvFailure(probeText)) {\n        // Conclusive the other way: the shell answered something that is not a\n        // PowerShell version (a POSIX \"command not found\" on stdout, or a\n        // non-zero exit with no output at all).\n        shellFlavor = 'bash'\n      } else {\n        // Inconclusive (no output and a clean exit): the platform default stands.\n        logInfo('[hdc-bridge] shell flavor probe inconclusive; keeping ' + shellFlavor)\n      }\n    } catch (e) {\n      // A probe that cannot run at all — sandbox backend refusal, executor not\n      // ready — says nothing about the dialect, so the platform default stands.\n      // Forcing 'bash' here sent POSIX quoting to pwsh, which turned every later\n      // command line into a parse error and surfaced as a bogus \"hdc not found\".\n      logInfo('[hdc-bridge] shell flavor probe unavailable (' + String(e && e.message ? e.message : 